  Future<void> supplierDialog([Supplier? old]) async {
    final name=TextEditingController(text:old?.name??''); final phone=TextEditingController(text:old?.phone??''); final address=TextEditingController(text:old?.address??'');
    await showDialog(context:context,builder:(_)=>AlertDialog(title:Text(old==null?'Add supplier':'Edit supplier'),content:SingleChildScrollView(child:Column(children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone')),TextField(controller:address,decoration:const InputDecoration(labelText:'Address'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()async{if(name.text.trim().isEmpty)return;final list=widget.store.suppliers;final x=Supplier(id:old?.id??id(),name:name.text.trim(),phone:phone.text.trim(),address:address.text.trim(),due:old?.due??0);if(old==null)list.add(x);else list[list.indexWhere((e)=>e.id==old.id)]=x;await widget.store.saveSuppliers(list);if(mounted)Navigator.pop(context);setState((){});},child:const Text('Save'))]));
