  Future<void> paymentDialog() async {
    final amount=TextEditingController(); final note=TextEditingController(); String type='received'; String party='';
    await showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(c,s){final customers=widget.store.customers;final suppliers=widget.store.suppliers;return AlertDialog(title:const Text('Add payment'),content:SingleChildScrollView(child:Column(children:[DropdownButtonFormField<String>(initialValue:type,items:const[DropdownMenuItem(value:'received',child:Text('Received from customer')),DropdownMenuItem(value:'paid',child:Text('Paid to supplier'))],onChanged:(v){if(v!=null)s(()=>type=v);}),const SizedBox(height:8),DropdownButtonFormField<String>(initialValue:party.isEmpty?null:party,items:[if(type=='received')...customers.map((e)=>DropdownMenuItem(value:e.id,child:Text(e.name))),if(type=='paid')...suppliers.map((e)=>DropdownMenuItem(value:e.id,child:Text(e.name)))],onChanged:(v)=>s(()=>party=v??''),decoration:const InputDecoration(labelText:'Party')),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount')),TextField(controller:note,decoration:const InputDecoration(labelText:'Note'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{final a=double.tryParse(amount.text)??0;if(a<=0||party.isEmpty)return;final p=Payment(id:id(),date:DateTime.now(),partyId:party,amount:a,note:note.text.trim(),type:type);final ps=widget.store.payments..add(p);await widget.store.savePayments(ps);if(type=='received'){final list=widget.store.customers;final i=list.indexWhere((e)=>e.id==party);if(i>=0){list[i].due-=a;await widget.store.saveCustomers(list);}}else{final list=widget.store.suppliers;final i=list.indexWhere((e)=>e.id==party);if(i>=0){list[i].due-=a;await widget.store.saveSuppliers(list);}}if(mounted)Navigator.pop(c);setState((){});},child:const Text('Save'))] }));
