  Future<void> stockMoveDialog() async {
    String product=''; String type='in'; final q=TextEditingController(); final note=TextEditingController();
    await showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(c,s)=>AlertDialog(title:const Text('Stock movement'),content:SingleChildScrollView(child:Column(children:[DropdownButtonFormField<String>(initialValue:product.isEmpty?null:product,items:[for(final p in widget.store.products)DropdownMenuItem(value:p.id,child:Text(p.name))],onChanged:(v)=>s(()=>product=v??''),decoration:const InputDecoration(labelText:'Product')),DropdownButtonFormField<String>(initialValue:type,items:const[DropdownMenuItem(value:'in',child:Text('Stock In')),DropdownMenuItem(value:'out',child:Text('Stock Out')),DropdownMenuItem(value:'adjustment',child:Text('Adjustment'))],onChanged:(v){if(v!=null)s(()=>type=v);}),TextField(controller:q,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantity')),TextField(controller:note,decoration:const InputDecoration(labelText:'Note'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{final n=double.tryParse(q.text)??0;if(product.isEmpty||n<=0)return;final list=widget.store.products;final i=list.indexWhere((e)=>e.id==product);if(i<0)return;final delta=type=='out'?-n:n;list[i].stock=(type=='adjustment'?n:list[i].stock+delta);if(list[i].stock<0)list[i].stock=0;await widget.store.saveProducts(list);await widget.store.saveStockMoves(widget.store.stockMoves..add(StockMove(id:id(),date:DateTime.now(),productId:product,quantity:n,type:type,note:note.text.trim())));if(mounted)Navigator.pop(c);setState((){});},child:const Text('Save'))]));
