  Future<void> returnDialog() async {
    final sales=widget.store.sales; String sale=''; String product=''; final q=TextEditingController(); final note=TextEditingController();
    await showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(c,s){final selected=sales.where((e)=>e.id==sale).toList();final items=selected.isEmpty?const <SaleItem>[]:selected.first.items;return AlertDialog(title:const Text('Sales return'),content:SingleChildScrollView(child:Column(children:[DropdownButtonFormField<String>(initialValue:sale.isEmpty?null:sale,items:[for(final x in sales)DropdownMenuItem(value:x.id,child:Text('#${x.id.substring(x.id.length-6)} • ${money(x.total)}'))],onChanged:(v){s((){sale=v??'';product='';});},decoration:const InputDecoration(labelText:'Sale')),DropdownButtonFormField<String>(initialValue:product.isEmpty?null:product,items:[for(final x in items)DropdownMenuItem(value:x.productId,child:Text(x.name))],onChanged:(v)=>s(()=>product=v??''),decoration:const InputDecoration(labelText:'Product')),TextField(controller:q,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantity')),TextField(controller:note,decoration:const InputDecoration(labelText:'Note'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{final n=double.tryParse(q.text)??0;final sl=sales.where((e)=>e.id==sale).toList();final it=sl.isEmpty?const <SaleItem>[]:sl.first.items.where((e)=>e.productId==product).toList();if(sl.isEmpty||it.isEmpty||n<=0||n>it.first.quantity)return;final amount=n*it.first.price;final ps=widget.store.products;final pi=ps.indexWhere((e)=>e.id==product);if(pi>=0){ps[pi].stock+=n;await widget.store.saveProducts(ps);}final rs=widget.store.returns..add(ReturnRecord(id:id(),date:DateTime.now(),saleId:sale,productId:product,quantity:n,amount:amount,note:note.text.trim()));await widget.store.saveReturns(rs);if(mounted)Navigator.pop(c);setState((){});},child:const Text('Save return'))] }));
    q.dispose();note.dispose();
  }

  void receipt(Sale sale) {
    final shop=widget.store.prefs.getString('shop')??'আমার দোকান';final currency=widget.store.prefs.getString('currency')??'৳';
    showDialog(context:context,builder:(_)=>AlertDialog(title:Text('$shop — Invoice ${sale.id.substring(sale.id.length-6)}'),content:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Date: ${sale.date}'),const Divider(),for(final i in sale.items)Padding(padding:const EdgeInsets.symmetric(vertical:3),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Expanded(child:Text('${i.name} × ${i.quantity}')),Text('$currency${i.subtotal.toStringAsFixed(2)}')])),const Divider(),Text('Total: $currency${sale.total.toStringAsFixed(2)}',style:const TextStyle(fontWeight:FontWeight.bold)),Text('Paid: $currency${sale.paid.toStringAsFixed(2)}'),Text('Due: $currency${sale.due.toStringAsFixed(2)}'),])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Close'))]));
  }

  @override Widget build(BuildContext context){final suppliers=widget.store.suppliers;final payments=widget.store.payments;final returns=widget.store.returns;final moves=widget.store.stockMoves;final sales=widget.store.sales;return Scaffold(appBar:AppBar(title:const Text('Business Tools')),body:Column(children:[SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[for(final x in ['Suppliers','Payments','Returns','Stock Moves','Invoices'])Padding(padding:const EdgeInsets.all(4),child:ChoiceChip(label:Text(x),selected:tab==['Suppliers','Payments','Returns','Stock Moves','Invoices'].indexOf(x),onSelected:(_){setState(()=>tab=['Suppliers','Payments','Returns','Stock Moves','Invoices'].indexOf(x));}})])),Expanded(child:ListView(padding:const EdgeInsets.all(12),children:[if(tab==0)...[for(final s in suppliers)Card(child:ListTile(title:Text(s.name),subtitle:Text('${s.phone}\nDue: ${money(s.due)}'),isThreeLine:true,onTap:()=>supplierDialog(s),trailing:IconButton(icon:const Icon(Icons.delete),onPressed:()async{final l=widget.store.suppliers..removeWhere((e)=>e.id==s.id);await widget.store.saveSuppliers(l);setState((){});})),),],if(tab==1)...[for(final p in payments)Card(child:ListTile(title:Text('${p.type=='received'?'Received':'Paid'} ${money(p.amount)}'),subtitle:Text('${p.date}\n${p.note}'),isThreeLine:true)),],if(tab==2)...[for(final r in returns)Card(child:ListTile(title:Text('Return ${money(r.amount)} • Qty ${r.quantity}'),subtitle:Text('Sale ${r.saleId} • Product ${r.productId}'))),],if(tab==3)...[for(final m in moves)Card(child:ListTile(title:Text('${m.type.toUpperCase()} • ${m.quantity}'),subtitle:Text('Product ${m.productId}\n${m.date}'),isThreeLine:true)),],if(tab==4)...[for(final s in sales)Card(child:ListTile(title:Text('Invoice ${s.id.substring(s.id.length-6)}'),subtitle:Text('${s.date} • ${money(s.total)}'),trailing:FilledButton(onPressed:()=>receipt(s),child:const Text('View')))),],if(tab==0&&suppliers.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(30),child:Text('No suppliers yet'))),if(tab==1&&payments.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(30),child:Text('No payments yet'))),if(tab==2&&returns.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(30),child:Text('No returns yet'))),if(tab==3&&moves.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(30),child:Text('No stock movements yet')))]))]),floatingActionButton:tab==0?FloatingActionButton.extended(onPressed:()=>supplierDialog(),icon:const Icon(Icons.person_add),label:const Text('Supplier')):tab==1?FloatingActionButton.extended(onPressed:paymentDialog,icon:const Icon(Icons.payments),label:const Text('Payment')):tab==2?FloatingActionButton.extended(onPressed:returnDialog,icon:const Icon(Icons.assignment_return),label:const Text('Return')):tab==3?FloatingActionButton.extended(onPressed:stockMoveDialog,icon:const Icon(Icons.swap_vert),label:const Text('Stock move')):null);}
